-- Private stories and a nameless public book (owner, 2026-10-20).
--
-- A story can be link-only: status 'unlisted', opened at /mykids?k=<share_key>, never listed on
-- /kids. The key is made in the Story Studio and can be replaced at any time, which retires the old
-- link. The words of a private story live only in D1 (pushed from the owner's machine); nothing
-- private is in this repository.
--
-- The public book's intro and goodnight no longer name anyone: version 2, published here, with its
-- narration baked into the site.

ALTER TABLE stories ADD COLUMN share_key TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS stories_share_key ON stories(share_key) WHERE share_key IS NOT NULL;

INSERT INTO story_versions(story, n, doc, note, author, created_at) SELECT 'my-own-home', COALESCE(MAX(n), 0) + 1, '{"title": "My Own Home, My Own Dome", "series": "Bedtime Stories", "voice": {"name": "en-US-JennyNeural", "rate": "-12%", "pitch": "+0Hz"}, "pages": [{"id": "intro-1", "kind": "intro", "scene": "stars", "text": "Hello, little one. Are you all cozy? Pull your blanket up, right up to your chin. There. Now look out the window, way up high, at all the twinkly stars. Do you see the brightest one? The one that blinks, like it''s saying hello? That one is watching over you tonight."}, {"id": "intro-2", "kind": "intro", "scene": "letter", "text": "Every so often, when the stars are just right, a story drifts across the ocean, all the way to your window. Tonight''s story is about a girl named Pip, who wanted a home with no corners at all. Are you ready? Here we go."}, {"id": "cover", "kind": "title", "scene": "cover", "text": "My Own Home, My Own Dome."}, {"id": "s1", "scene": "town", "text": "In a town full of boxes, all stacked up so tall,\nlived a girl named Pip Pine who said, \"Boxes? Not all!\nA box has four corners, and corners grow dust.\nI want a round home. A round home! I must!\"", "kind": "page"}, {"id": "s2", "scene": "dream", "text": "\"A dome!\" Pip decided. \"A dome I will build,\nwith a roof like the sky when the sky is all filled\nwith the curve of the morning, the bend of the sun --\na home with no corners! Not one! Not a one!\"", "kind": "page"}, {"id": "s3", "scene": "lumber", "text": "So she marched past the lumber yard, stacked to the eaves\nwith boards wrapped in plastic and tags on their sleeves.\n\"No thank you,\" said Pip. \"I won''t buy all my sticks.\nI will find them, and split them, and fit them like bricks.\"", "kind": "page"}, {"id": "s4", "scene": "log", "text": "At the edge of the forest a fallen pine lay,\njust as round as a barrel and long as a day.\n\"Hello, Mister Log,\" Pip said, tipping her hat.\n\"Would you like to be home? Would you, please, become that?\"", "kind": "page"}, {"id": "s5", "scene": "tools", "text": "The log didn''t answer (most logs never talk),\nso Pip took the silence as \"Yes!\" and a \"Walk!\"\nShe fetched one good saw and one bright chalky line,\none level, one tape, and one lunch box. Just fine.", "kind": "page"}, {"id": "s6", "scene": "zzzip", "text": "Zzzip! went the saw, and the log split in two.\nZzzip! went the saw, and the twos split anew.\nThen halves became quarters, and quarters made eight --\neight wedges like pie slices stacked on a plate.", "kind": "page"}, {"id": "s7", "scene": "wedges", "text": "\"A wedge,\" Pip declared, \"is a bone of my dome!\nEach wedge is a rib of my own little home.\nI''ll cut them to length -- not too short, not too long --\nfor a strut that''s too short makes a dome that goes wrong.\"", "kind": "page"}, {"id": "s8", "scene": "chalk", "text": "She measured one strut, just the longest of all,\nand she wrote it in chalk on the side of the wall.\n\"From this one little number,\" said Pip with a grin,\n\"I can count out the whole of the house I''ll live in!\"", "kind": "page"}, {"id": "s9", "scene": "measure", "text": "\"How tall? And how wide? And how much will it weigh?\nHow many triangles? How long will it stay?\nIt''s all in the number. The number''s the key.\nIf I know my long strut, then my dome will know me.\"", "kind": "page"}, {"id": "s10", "scene": "pinwheel", "text": "Then wedge after wedge went in pinwheels of three,\neach one leaning on one, like a hug, don''t you see?\nNo nails at the corners, no hubs made of tin,\njust a wedge holding wedge holding wedge holding in.", "kind": "page"}, {"id": "s11", "scene": "rising", "text": "Triangle! Triangle! Up the ring rose,\nlittle triangle windows in tidy round rows,\nand the rows bent together and curved toward the top,\ntill the very last triangle -- click! -- made it stop.", "kind": "page"}, {"id": "s12", "scene": "neighbours", "text": "The neighbours came running. \"What IS that?\" they cried.\n\"It is round on the outside! It''s round on the inside!\"\n\"It''s my home,\" Pip said proudly. \"My dome. It is mine.\nI can tell you its weight. I can tell you each line.\"", "kind": "page"}, {"id": "s13", "scene": "ledger", "text": "\"I can tell you the wood and the screws that it took.\nI can tell you the hours -- they''re all in my book.\nThere''s no secret, no guess, no ''oh, roughly, we think'' --\njust numbers you count, written down in black ink.\"", "kind": "page"}, {"id": "s14", "scene": "panel", "text": "Then a boy from the boxes came up with a frown.\n\"My dome has a hole, and a panel fell down.\"\nPip asked, \"What''s your long strut?\" He said, \"Same as yours!\"\n\"Then my panels fit yours, like the doors fit their doors!\"", "kind": "page"}, {"id": "s15", "scene": "club", "text": "So the kids with same domes started up a big club,\nwhere they swapped out their panels and shared tools and grub,\nand they learned from each other which way the wind blows,\nand which wedge goes where, and how everyone grows.", "kind": "page"}, {"id": "s16", "scene": "night", "text": "Now the town full of boxes has domes on the hill,\nlittle round ones and big ones, and more coming still.\nAnd at night, when the sky makes a dome of its own,\nPip curls up in hers. \"My own dome. My own home.\"", "kind": "page"}, {"id": "outro", "kind": "outro", "scene": "goodnight", "text": "The end. Goodnight, little one. Look, the brightest star is shining right over your house tonight. Remember three things. Be kind. Be curious. And always help each other build. Sweet dreams."}], "figures": {"longIn": 72, "shortIn": 63.67, "members": 120, "triangles": 40, "woodCuft": 65.22, "frameLb": 2478, "frameCost": 2465, "hours": "37.5", "diameterFt": 19.42, "heightFt": 9.71}}', 'A bedtime story for anyone: no names in the hello and goodnight', 'seed', '2026-10-20T00:00:00Z' FROM story_versions WHERE story = 'my-own-home';
